-- 20270217000053 - credit settle guards, RE-AUTHORED ON THE LIVE BODIES (e1; e9-ruled BLOCKING for the enforcement flip
-- and the pricing release; version reserved by virality-83; review: virality-05). GENERATED by
-- scripts/migrations/gen-053-credit-settle-guards.py from backend/tests/fixtures/live-credit-functions-20261113 (the C100
-- extraction, md5 = prod md5(prosrc)). Do not hand-edit the function bodies: change the generator and re-run it.
--
-- WHAT IS LIVE (C98/C99/C100, 2026-11-13):
--   apply_credit_reservation     = 20260322_expiry_category_guard (md5 ad5383bf6ccf24a2c8ddee70db3b1297)
--   apply_credit_partial_confirm = a hand-applied body matching NO repo file (md5 ff208f60617a7a272305a804037bf47d)
--   expire_org_free_credits      = 20260323_remove_balance_credits (md5 ae410c7ab297eebe2890a7f925d95f04)
--
-- NOT A REPLAY (05). THREE divergent replacements of apply_credit_reservation exist in the repo, NONE live:
--   20260322_wallet_reservation (never ran - a version collision), 20260323_remove_balance_credits (has a ledger row,
--   its body is not live), 20260625_monetization_invariant_hardening (never ran). 053 does not re-run any of them: it
--   reconciles their INTENT - chiefly 20260625's settle guards - against the live bodies, carrying over only guards.
--
-- GUARDS ADDED (each a money defect on the live body; 05/e9 review 2026-11-13):
--   both functions:
--     - NULL or negative amounts refused (a negative HOLD raised the balance);
--     - the idempotency key is REQUIRED (a keyless retry applied twice);
--     - a hold settles ONCE: a confirm / confirm_partial / release child already present -> HOLD_ALREADY_SETTLED
--       (release-after-confirm refunded consumed credits; double release refunded twice). The check runs after the
--       org's wallet row lock, which both functions take first, so it is race-free per org;
--     - unique_violation: only a collision on the idempotency KEY ('credit_transactions_idempotency_key_key', 'credit_transactions_idempotency_key_lockdown_unique', 'idx_credit_txn_idempotency')
--       is a replay; anything else re-raises; a key collision with no row raises (no success-shaped {id:null}).
--   apply_credit_reservation only:
--     - confirm/release REQUIRE p_parent_id naming this org's 'hold' row; other phases refuse a parent;
--     - a settle may not exceed the hold's own split nor the wallet's reserved_* (the live GREATEST(0, ...) clamp hid it);
--     - HOLD AVAILABILITY no longer subtracts reserved_* a second time (e9 BLOCKING-launch: every open hold was counted
--       twice, refusing customers with spendable credits). Paired TS change: creditPriorityService.computeAvailable.
-- KEPT AS LIVE (losing nothing): every phase's wallet arithmetic, the expire / expire_incentive clamp semantics, the
-- partial-confirm consume/release/excess/underfunded logic, both search_paths, invoker rights, service_role-only EXECUTE.
-- DROPPED: expire_org_free_credits (20260625 intended it; no caller in code, SQL bodies, triggers or pg_cron - the
-- preflight ABORTS if any reference exists, so the drop never strands a caller).
-- SPLIT OUT (e9 allowed): the expiry leak on RELEASE (held free credits escaping their grant's expiry) needs per-grant
-- lot tracking - a follow-up version, not 053.
--
-- PRE-REQUISITE AT APPLY: the preflight accepts exactly the known bodies (prod md5, or the 20260625 repo body a CI
-- replay produces) and refuses anything else - an unknown body means prod moved and 053 must be re-generated.

DO $preflight$
DECLARE
  v_res text;
  v_pc  text;
  v_refs int;
BEGIN
  SELECT prosrc INTO v_res FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text)');
  SELECT prosrc INTO v_pc  FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid)');
  IF v_res IS NULL OR v_pc IS NULL THEN
    RAISE EXCEPTION '053 preflight: apply_credit_reservation / apply_credit_partial_confirm (exact signatures) missing';
  END IF;
  IF NOT (md5(v_res) = 'ad5383bf6ccf24a2c8ddee70db3b1297' OR position('already settled by' IN v_res) > 0
          OR md5(v_res) = '5242c45fa92183090997c4bb4f6b8189') THEN
    RAISE EXCEPTION '053 preflight: apply_credit_reservation body is unknown (md5 %) - prod moved; re-generate 053', md5(v_res);
  END IF;
  IF NOT (md5(v_pc) = 'ff208f60617a7a272305a804037bf47d' OR position('already settled by' IN v_pc) > 0
          OR md5(v_pc) = '71b0c840b1eb3116b4e53ec840aa4d19') THEN
    RAISE EXCEPTION '053 preflight: apply_credit_partial_confirm body is unknown (md5 %) - prod moved; re-generate 053', md5(v_pc);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'credit_transactions'
                  AND column_name = 'parent_transaction_id') THEN
    RAISE EXCEPTION '053 preflight: credit_transactions.parent_transaction_id is missing';
  END IF;
  -- expire_org_free_credits may be dropped only if NOTHING references it.
  IF to_regprocedure('public.expire_org_free_credits(uuid,integer,text)') IS NOT NULL THEN
    SELECT count(*) INTO v_refs FROM pg_proc
     WHERE prosrc ILIKE '%expire_org_free_credits%' AND oid <> to_regprocedure('public.expire_org_free_credits(uuid,integer,text)');
    IF v_refs > 0 THEN
      RAISE EXCEPTION '053 preflight: % function body(ies) reference expire_org_free_credits - it cannot be dropped', v_refs;
    END IF;
    IF to_regclass('cron.job') IS NOT NULL THEN
      EXECUTE 'SELECT count(*) FROM cron.job WHERE command ILIKE ''%expire_org_free_credits%''' INTO v_refs;
      IF v_refs > 0 THEN
        RAISE EXCEPTION '053 preflight: % pg_cron job(s) call expire_org_free_credits - it cannot be dropped', v_refs;
      END IF;
    END IF;
  END IF;
END
$preflight$;

CREATE OR REPLACE FUNCTION public.apply_credit_reservation(
  p_org_id           uuid,
  p_phase            text,
  p_free_amount      int  DEFAULT 0,
  p_incentive_amount int  DEFAULT 0,
  p_paid_amount      int  DEFAULT 0,
  p_idempotency_key  text DEFAULT NULL,
  p_reference_type   text DEFAULT NULL,
  p_reference_id     text DEFAULT NULL,
  p_note             text DEFAULT NULL,
  p_performed_by     uuid DEFAULT NULL,
  p_parent_id        uuid DEFAULT NULL,
  p_category         text DEFAULT 'paid'
) RETURNS jsonb
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $fn$
DECLARE
  v_wallet   organization_credits%ROWTYPE;
  v_tx_row   credit_transactions%ROWTYPE;
  v_avail_free      int;
  v_avail_incentive int;
  v_avail_paid      int;
  v_tx_type  text;
  v_free_delta      int := 0;
  v_incentive_delta int := 0;
  v_paid_delta      int := 0;
  v_hold            credit_transactions%ROWTYPE;
  v_settled_id      uuid;
  v_constraint      text;
BEGIN
  -- ── 053 guard: amounts and key (20260625 intent; refusals, never silent clamps) ─────────────────────────────
  IF p_free_amount IS NULL OR p_incentive_amount IS NULL OR p_paid_amount IS NULL THEN
    RAISE EXCEPTION 'CREDIT_AMOUNT_NULL: phase=%', p_phase USING ERRCODE = 'P0001';
  END IF;
  IF p_free_amount < 0 OR p_incentive_amount < 0 OR p_paid_amount < 0 THEN
    RAISE EXCEPTION 'CREDIT_AMOUNT_NEGATIVE: phase=% free=% incentive=% paid=%',
      p_phase, p_free_amount, p_incentive_amount, p_paid_amount USING ERRCODE = 'P0001';
  END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'CREDIT_IDEMPOTENCY_KEY_REQUIRED: phase=%', p_phase USING ERRCODE = 'P0001';
  END IF;

  -- ── Idempotency: return existing row if key already processed ───────────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF FOUND THEN
      RETURN row_to_json(v_tx_row)::jsonb;
    END IF;
  END IF;

  -- ── Lock the wallet row for this operation ──────────────────────────────────
  SELECT * INTO v_wallet
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO organization_credits (organization_id)
    VALUES (p_org_id)
    ON CONFLICT (organization_id) DO NOTHING;

    SELECT * INTO v_wallet
      FROM organization_credits
     WHERE organization_id = p_org_id
     FOR UPDATE;
  END IF;

  -- ── 053 guard: settle integrity (runs AFTER the wallet lock, which serialises every credit write of this org) ──
  IF p_phase IN ('confirm', 'release') THEN
    IF p_parent_id IS NULL THEN
      RAISE EXCEPTION 'SETTLE_REQUIRES_PARENT_HOLD: phase=%', p_phase USING ERRCODE = 'P0001';
    END IF;
    SELECT * INTO v_hold FROM credit_transactions WHERE id = p_parent_id;
    IF NOT FOUND OR v_hold.organization_id IS DISTINCT FROM p_org_id OR v_hold.execution_phase IS DISTINCT FROM 'hold' THEN
      RAISE EXCEPTION 'SETTLE_PARENT_NOT_A_HOLD: parent=% org=%', p_parent_id, p_org_id USING ERRCODE = 'P0001';
    END IF;
    SELECT id INTO v_settled_id FROM credit_transactions
     WHERE parent_transaction_id = p_parent_id AND execution_phase IN ('confirm', 'confirm_partial', 'release')
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'HOLD_ALREADY_SETTLED: hold=% by transaction %', p_parent_id, v_settled_id USING ERRCODE = 'P0001';
    END IF;
    IF p_free_amount      > ABS(COALESCE(v_hold.free_delta, 0))
       OR p_incentive_amount > ABS(COALESCE(v_hold.incentive_delta, 0))
       OR p_paid_amount      > ABS(COALESCE(v_hold.paid_delta, 0)) THEN
      RAISE EXCEPTION 'SETTLE_EXCEEDS_HOLD: hold=%', p_parent_id USING ERRCODE = 'P0001';
    END IF;
    IF p_free_amount      > v_wallet.reserved_free
       OR p_incentive_amount > v_wallet.reserved_incentive
       OR p_paid_amount      > v_wallet.reserved_paid THEN
      RAISE EXCEPTION 'SETTLE_EXCEEDS_RESERVED: hold=%', p_parent_id USING ERRCODE = 'P0001';
    END IF;
  ELSIF p_parent_id IS NOT NULL THEN
    RAISE EXCEPTION 'PARENT_ONLY_FOR_SETTLE: phase=%', p_phase USING ERRCODE = 'P0001';
  END IF;

  -- ── Phase dispatch ──────────────────────────────────────────────────────────

  IF p_phase = 'hold' THEN
    -- 053: a HOLD moves credits OUT of *_balance INTO reserved_* (see the UPDATE below), so *_balance already excludes
    -- every open hold. The live body subtracted reserved_* AGAIN, counting each open hold twice and refusing customers
    -- who had spendable credits. Availability is the balance itself (same definition as creditPriorityService).
    v_avail_free      := GREATEST(0, v_wallet.free_balance);
    v_avail_incentive := GREATEST(0, v_wallet.incentive_balance);
    v_avail_paid      := GREATEST(0, v_wallet.paid_balance);

    IF p_free_amount > v_avail_free THEN
      RAISE EXCEPTION 'insufficient free balance: need %, have %', p_free_amount, v_avail_free;
    END IF;
    IF p_incentive_amount > v_avail_incentive THEN
      RAISE EXCEPTION 'insufficient incentive balance: need %, have %', p_incentive_amount, v_avail_incentive;
    END IF;
    IF p_paid_amount > v_avail_paid THEN
      RAISE EXCEPTION 'insufficient paid balance: need %, have %', p_paid_amount, v_avail_paid;
    END IF;

    UPDATE organization_credits SET
      free_balance      = free_balance      - p_free_amount,
      incentive_balance = incentive_balance - p_incentive_amount,
      paid_balance      = paid_balance      - p_paid_amount,
      reserved_free     = reserved_free     + p_free_amount,
      reserved_incentive= reserved_incentive+ p_incentive_amount,
      reserved_paid     = reserved_paid     + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_free_delta     := -p_free_amount;
    v_incentive_delta:= -p_incentive_amount;
    v_paid_delta     := -p_paid_amount;

  ELSIF p_phase = 'confirm' THEN
    UPDATE organization_credits SET
      reserved_free     = GREATEST(0, reserved_free      - p_free_amount),
      reserved_incentive= GREATEST(0, reserved_incentive - p_incentive_amount),
      reserved_paid     = GREATEST(0, reserved_paid      - p_paid_amount),
      lifetime_consumed = lifetime_consumed + p_free_amount + p_incentive_amount + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_free_delta     := -p_free_amount;
    v_incentive_delta:= -p_incentive_amount;
    v_paid_delta     := -p_paid_amount;

  ELSIF p_phase = 'release' THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      + p_free_amount,
      incentive_balance = incentive_balance + p_incentive_amount,
      paid_balance      = paid_balance      + p_paid_amount,
      reserved_free     = GREATEST(0, reserved_free      - p_free_amount),
      reserved_incentive= GREATEST(0, reserved_incentive - p_incentive_amount),
      reserved_paid     = GREATEST(0, reserved_paid      - p_paid_amount),
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'refund';
    v_free_delta     := p_free_amount;
    v_incentive_delta:= p_incentive_amount;
    v_paid_delta     := p_paid_amount;

  ELSIF p_phase = 'grant' THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      + p_free_amount,
      incentive_balance = incentive_balance + p_incentive_amount,
      paid_balance      = paid_balance      + p_paid_amount,
      lifetime_purchased= lifetime_purchased + p_free_amount + p_incentive_amount + p_paid_amount,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'purchase';
    v_free_delta     := p_free_amount;
    v_incentive_delta:= p_incentive_amount;
    v_paid_delta     := p_paid_amount;

  ELSIF p_phase = 'expire' THEN
    -- ── CATEGORY GUARD: expire can only drain free_balance ──────────────────
    -- Paid credits never expire. Incentive credits are expired via a separate
    -- controlled path with explicit config opt-in. Any caller that accidentally
    -- passes non-zero values here gets a hard failure, not a silent no-op.
    IF p_incentive_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire phase cannot touch incentive_balance (p_incentive_amount=%)',
        p_incentive_amount;
    END IF;
    IF p_paid_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire phase cannot touch paid_balance (p_paid_amount=%)',
        p_paid_amount;
    END IF;

    -- Only free_balance is reduced. GREATEST(0, ...) prevents going negative.
    UPDATE organization_credits SET
      free_balance = GREATEST(0, free_balance - p_free_amount),
      updated_at   = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type    := 'deduction';
    v_free_delta := -LEAST(p_free_amount, v_wallet.free_balance);

  ELSIF p_phase = 'expire_incentive' THEN
    -- ── Incentive expiry — separate, explicitly named phase ─────────────────
    -- Only callable when the incentive_expiry config row has is_active=true.
    -- Paid credits are never touched here either.
    IF p_paid_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire_incentive phase cannot touch paid_balance (p_paid_amount=%)',
        p_paid_amount;
    END IF;
    IF p_free_amount <> 0 THEN
      RAISE EXCEPTION
        'EXPIRY_CATEGORY_GUARD: expire_incentive phase cannot touch free_balance (p_free_amount=%)',
        p_free_amount;
    END IF;

    UPDATE organization_credits SET
      incentive_balance = GREATEST(0, incentive_balance - p_incentive_amount),
      updated_at        = NOW()
    WHERE organization_id = p_org_id;

    v_tx_type        := 'deduction';
    v_incentive_delta:= -LEAST(p_incentive_amount, v_wallet.incentive_balance);

  ELSE
    RAISE EXCEPTION 'unknown phase: %', p_phase;
  END IF;

  -- ── Append ledger row ───────────────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    free_delta,
    paid_delta,
    incentive_delta,
    created_at
  )
  SELECT
    p_org_id,
    v_tx_type,
    v_free_delta + v_incentive_delta + v_paid_delta,
    oc.free_balance + oc.paid_balance + oc.incentive_balance,
    p_reference_type,
    p_reference_id::uuid,
    p_note,
    p_performed_by,
    p_idempotency_key,
    p_phase,
    p_parent_id,
    p_category,
    v_free_delta,
    v_paid_delta,
    v_incentive_delta,
    NOW()
  FROM organization_credits oc
  WHERE oc.organization_id = p_org_id
  RETURNING * INTO v_tx_row;

  RETURN row_to_json(v_tx_row)::jsonb;

EXCEPTION
  WHEN unique_violation THEN
    -- 053: only a collision on the IDEMPOTENCY KEY is a replay; any other unique rule is a real error. A key
    -- collision with no row behind it is raised too - never a success-shaped {id:null}.
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint IS NULL OR v_constraint NOT IN ('credit_transactions_idempotency_key_key', 'credit_transactions_idempotency_key_lockdown_unique', 'idx_credit_txn_idempotency') THEN
      RAISE;
    END IF;
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'CREDIT_IDEMPOTENCY_COLLISION_WITHOUT_ROW: %', p_idempotency_key USING ERRCODE = 'P0001';
    END IF;
    RETURN row_to_json(v_tx_row)::jsonb;
END;
$fn$;
REVOKE ALL ON FUNCTION public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text) TO service_role;

CREATE OR REPLACE FUNCTION public.apply_credit_partial_confirm(
  p_org_id uuid,
  p_hold_txn_id uuid,
  p_actual_free int DEFAULT 0,
  p_actual_incentive int DEFAULT 0,
  p_actual_paid int DEFAULT 0,
  p_idempotency_key text DEFAULT NULL,
  p_reference_type text DEFAULT NULL,
  p_reference_id text DEFAULT NULL,
  p_note text DEFAULT NULL,
  p_performed_by uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SET search_path = public, extensions
AS $fn$
DECLARE
  v_tx_row       credit_transactions%ROWTYPE;
  v_hold         credit_transactions%ROWTYPE;

  v_held_free       int;
  v_held_incentive  int;
  v_held_paid       int;

  v_consume_free    int;
  v_consume_incentive int;
  v_consume_paid    int;

  v_excess_free     int;
  v_excess_incentive int;
  v_excess_paid     int;

  v_release_free    int;
  v_release_incentive int;
  v_release_paid    int;

  v_wallet          organization_credits%ROWTYPE;
  v_extra_free      int := 0;
  v_extra_incentive int := 0;
  v_extra_paid      int := 0;
  v_shortfall_free  int := 0;
  v_shortfall_incentive int := 0;
  v_shortfall_paid  int := 0;
  v_is_underfunded  boolean := false;

  v_consumed_total  int;
  v_released_total  int;
  v_settled_id      uuid;
  v_constraint      text;
BEGIN
  -- ── 053 guard: amounts and key ─────────────────────────────────────────────────────────────────────────────
  IF p_actual_free IS NULL OR p_actual_incentive IS NULL OR p_actual_paid IS NULL THEN
    RAISE EXCEPTION 'CREDIT_AMOUNT_NULL: partial confirm of hold %', p_hold_txn_id USING ERRCODE = 'P0001';
  END IF;
  IF p_actual_free < 0 OR p_actual_incentive < 0 OR p_actual_paid < 0 THEN
    RAISE EXCEPTION 'CREDIT_AMOUNT_NEGATIVE: partial confirm of hold %', p_hold_txn_id USING ERRCODE = 'P0001';
  END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'CREDIT_IDEMPOTENCY_KEY_REQUIRED: partial confirm of hold %', p_hold_txn_id USING ERRCODE = 'P0001';
  END IF;

  -- ── Idempotency ───────────────────────────────────────────────────────────
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF FOUND THEN
      RETURN row_to_json(v_tx_row)::jsonb;
    END IF;
  END IF;

  -- ── Load and validate parent HOLD ─────────────────────────────────────────
  SELECT * INTO v_hold
    FROM credit_transactions
   WHERE id = p_hold_txn_id
     AND organization_id = p_org_id
     AND execution_phase = 'hold';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_hold_found: hold_txn_id=% org=%', p_hold_txn_id, p_org_id;
  END IF;

  -- HOLD deltas are stored NEGATIVE (outflow); flip sign to get held amounts
  v_held_free      := ABS(COALESCE(v_hold.free_delta, 0));
  v_held_incentive := ABS(COALESCE(v_hold.incentive_delta, 0));
  v_held_paid      := ABS(COALESCE(v_hold.paid_delta, 0));

  -- Per-category split:
  --   consume = min(actual, held)
  --   excess  = max(actual - held, 0)   -- needs to come from balance
  --   release = held - consume          -- unused reservation returned
  v_consume_free      := LEAST(p_actual_free,      v_held_free);
  v_consume_incentive := LEAST(p_actual_incentive, v_held_incentive);
  v_consume_paid      := LEAST(p_actual_paid,      v_held_paid);

  v_excess_free       := GREATEST(p_actual_free      - v_held_free,      0);
  v_excess_incentive  := GREATEST(p_actual_incentive - v_held_incentive, 0);
  v_excess_paid       := GREATEST(p_actual_paid      - v_held_paid,      0);

  v_release_free      := v_held_free      - v_consume_free;
  v_release_incentive := v_held_incentive - v_consume_incentive;
  v_release_paid      := v_held_paid      - v_consume_paid;

  -- ── Lock wallet and apply ─────────────────────────────────────────────────
  SELECT * INTO v_wallet
    FROM organization_credits
   WHERE organization_id = p_org_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no_credit_account: org %', p_org_id;
  END IF;

  -- ── 053 guard: a hold settles ONCE (after the wallet lock, which serialises every credit write of this org) ──
  SELECT id INTO v_settled_id FROM credit_transactions
   WHERE parent_transaction_id = p_hold_txn_id AND execution_phase IN ('confirm', 'confirm_partial', 'release')
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'HOLD_ALREADY_SETTLED: hold=% by transaction %', p_hold_txn_id, v_settled_id USING ERRCODE = 'P0001';
  END IF;

  -- 1. Consume from reserved (the "CONFIRM" part):
  --    reserved_X -= consume_X
  --    lifetime_consumed += consume_X
  -- 2. Release unused reservation (the "RELEASE" part):
  --    reserved_X -= release_X
  --    balance_X  += release_X
  -- 3. Excess consumption — try to pull from balance; underfunded if insufficient:
  --    take = min(excess, balance_after_release)
  --    balance_X  -= take
  --    lifetime_consumed += take
  --    shortfall_X = excess - take

  -- Apply (1) + (2) first, then compute excess from updated balance
  UPDATE organization_credits SET
    reserved_free      = GREATEST(0, reserved_free      - v_consume_free      - v_release_free),
    reserved_incentive = GREATEST(0, reserved_incentive - v_consume_incentive - v_release_incentive),
    reserved_paid      = GREATEST(0, reserved_paid      - v_consume_paid      - v_release_paid),
    free_balance       = free_balance      + v_release_free,
    incentive_balance  = incentive_balance + v_release_incentive,
    paid_balance       = paid_balance      + v_release_paid,
    lifetime_consumed  = lifetime_consumed + v_consume_free + v_consume_incentive + v_consume_paid,
    updated_at         = NOW()
  WHERE organization_id = p_org_id
  RETURNING * INTO v_wallet;

  -- (3) Excess from balance
  IF v_excess_free > 0 THEN
    v_extra_free     := LEAST(v_excess_free, v_wallet.free_balance);
    v_shortfall_free := v_excess_free - v_extra_free;
  END IF;
  IF v_excess_incentive > 0 THEN
    v_extra_incentive     := LEAST(v_excess_incentive, v_wallet.incentive_balance);
    v_shortfall_incentive := v_excess_incentive - v_extra_incentive;
  END IF;
  IF v_excess_paid > 0 THEN
    v_extra_paid     := LEAST(v_excess_paid, v_wallet.paid_balance);
    v_shortfall_paid := v_excess_paid - v_extra_paid;
  END IF;

  IF (v_extra_free + v_extra_incentive + v_extra_paid) > 0 THEN
    UPDATE organization_credits SET
      free_balance      = free_balance      - v_extra_free,
      incentive_balance = incentive_balance - v_extra_incentive,
      paid_balance      = paid_balance      - v_extra_paid,
      lifetime_consumed = lifetime_consumed + v_extra_free + v_extra_incentive + v_extra_paid,
      updated_at        = NOW()
    WHERE organization_id = p_org_id;
  END IF;

  v_is_underfunded := (v_shortfall_free + v_shortfall_incentive + v_shortfall_paid) > 0;

  v_consumed_total := v_consume_free + v_consume_incentive + v_consume_paid
                    + v_extra_free   + v_extra_incentive   + v_extra_paid;
  v_released_total := v_release_free + v_release_incentive + v_release_paid;

  -- ── Append ledger row ─────────────────────────────────────────────────────
  INSERT INTO credit_transactions (
    organization_id,
    transaction_type,
    credits_delta,
    balance_after,
    reference_type,
    reference_id,
    note,
    performed_by,
    idempotency_key,
    execution_phase,
    parent_transaction_id,
    category,
    free_delta,
    paid_delta,
    incentive_delta,
    is_underfunded,
    created_at
  )
  VALUES (
    p_org_id,
    'deduction',
    -v_consumed_total,
    (v_wallet.free_balance + v_wallet.paid_balance + v_wallet.incentive_balance)
      - v_extra_free - v_extra_incentive - v_extra_paid,
    p_reference_type,
    p_reference_id::uuid,
    COALESCE(p_note, 'confirm_partial') ||
      CASE WHEN v_is_underfunded
           THEN ' [UNDERFUNDED shortfall_total=' ||
                (v_shortfall_free + v_shortfall_incentive + v_shortfall_paid) || ']'
           ELSE '' END,
    p_performed_by,
    p_idempotency_key,
    'confirm_partial',
    p_hold_txn_id,
    'paid',
    -(v_consume_free      + v_extra_free),
    -(v_consume_paid      + v_extra_paid),
    -(v_consume_incentive + v_extra_incentive),
    v_is_underfunded,
    NOW()
  )
  RETURNING * INTO v_tx_row;

  RETURN jsonb_build_object(
    'id',                 v_tx_row.id,
    'consumed_free',      v_consume_free      + v_extra_free,
    'consumed_incentive', v_consume_incentive + v_extra_incentive,
    'consumed_paid',      v_consume_paid      + v_extra_paid,
    'released_free',      v_release_free,
    'released_incentive', v_release_incentive,
    'released_paid',      v_release_paid,
    'shortfall_free',     v_shortfall_free,
    'shortfall_incentive',v_shortfall_incentive,
    'shortfall_paid',     v_shortfall_paid,
    'is_underfunded',     v_is_underfunded,
    'total_consumed',     v_consumed_total,
    'total_released',     v_released_total
  );

EXCEPTION
  WHEN unique_violation THEN
    -- 053: only a collision on the IDEMPOTENCY KEY is a replay; any other unique rule is a real error. A key
    -- collision with no row behind it is raised too - never a success-shaped {id:null}.
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint IS NULL OR v_constraint NOT IN ('credit_transactions_idempotency_key_key', 'credit_transactions_idempotency_key_lockdown_unique', 'idx_credit_txn_idempotency') THEN
      RAISE;
    END IF;
    SELECT * INTO v_tx_row
      FROM credit_transactions
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'CREDIT_IDEMPOTENCY_COLLISION_WITHOUT_ROW: %', p_idempotency_key USING ERRCODE = 'P0001';
    END IF;
    RETURN row_to_json(v_tx_row)::jsonb;
END;
$fn$;
REVOKE ALL ON FUNCTION public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid) TO service_role;

DROP FUNCTION IF EXISTS public.expire_org_free_credits(uuid,integer,text);

DO $verify$
DECLARE
  r text;
BEGIN
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text)')) IS DISTINCT FROM '5242c45fa92183090997c4bb4f6b8189' THEN
    RAISE EXCEPTION '053 postcondition: apply_credit_reservation body is not the generated one';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid)')) IS DISTINCT FROM '71b0c840b1eb3116b4e53ec840aa4d19' THEN
    RAISE EXCEPTION '053 postcondition: apply_credit_partial_confirm body is not the generated one';
  END IF;
  IF (SELECT prosecdef FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text)'))
     OR (SELECT prosecdef FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid)')) THEN
    RAISE EXCEPTION '053 postcondition: a credit function became SECURITY DEFINER (live: invoker rights)';
  END IF;
  IF NOT (SELECT proconfig @> ARRAY['search_path=pg_catalog, public'] FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text)'))
     OR NOT (SELECT proconfig @> ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid = to_regprocedure('public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid)')) THEN
    RAISE EXCEPTION '053 postcondition: a credit function lost its live search_path';
  END IF;
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF has_function_privilege(r, 'public.apply_credit_reservation(uuid,text,integer,integer,integer,text,text,text,text,uuid,uuid,text)', 'EXECUTE') OR has_function_privilege(r, 'public.apply_credit_partial_confirm(uuid,uuid,integer,integer,integer,text,text,text,text,uuid)', 'EXECUTE') THEN
      RAISE EXCEPTION '053 postcondition: % can execute a credit settle function', r;
    END IF;
  END LOOP;
  IF to_regprocedure('public.expire_org_free_credits(uuid,integer,text)') IS NOT NULL THEN
    RAISE EXCEPTION '053 postcondition: expire_org_free_credits still exists';
  END IF;
END
$verify$;

